/// Compte Telegram REEL (pas un bot) portant une persona de l'assistant : il n'affiche pas le badge « bot »,
/// il peut ecrire le premier, et il lit les messages par une connexion longue (MTProto).
model TelegramUserAccount {
  id               String    @id @default(cuid())
  /// Nom interne (« Lea »).
  label            String
  /// Numero au format international (+33612345678).
  phone            String    @unique
  /// Session GramJS (StringSession) chiffree AES-256-GCM.
  sessionEncrypted String
  /// PENDING_CODE | PENDING_PASSWORD | ACTIVE | ERROR | DISCONNECTED
  status           String    @default("PENDING_CODE")
  /// Code envoye par Telegram, garde entre l'envoi et la saisie.
  phoneCodeHash    String?
  /// Persona portee par ce compte.
  personaId        String?
  persona          Persona?  @relation(fields: [personaId], references: [id], onDelete: SetNull)
  /// Identite Telegram, une fois connecte.
  telegramUserId   BigInt?
  telegramUsername String?
  /// Proxy SOCKS5 facultatif (hote:port).
  proxyUrl         String?
  /// Plafonds anti-bannissement.
  dailyCap           Int       @default(60)
  newConversationCap Int       @default(20)
  /// Paliers de montee en charge (jours depuis la connexion).
  warmupDay          Int       @default(0)
  isActive           Boolean   @default(false)
  lastActiveAt       DateTime?
  lastError          String?
  createdAt          DateTime  @default(now())
  updatedAt          DateTime  @updatedAt

  /// Bot fantome qui porte les conversations de ce compte. L'API bot n'est pas utilisee :
  /// la reception et l'envoi passent par la session MTProto tenue par apps/userbot.
  botId            String?   @unique
  bot              Bot?      @relation(fields: [botId], references: [id], onDelete: SetNull)

  @@index([status])
  @@index([isActive])
  offerLinks AssistantOfferLink[]
  clicks     Click[]
  usages     AiConversationUsage[]

  @@unique([botId, memberId])
  @@index([status, nextFollowUpAt])
  @@index([status, retryAt])
  @@index([personaId, createdAt])
  @@index([source])
  @@index([lastInboundAt])
  @@index([memberId])
}

/// Message d'une conversation (texte brut, jamais de HTML). Purgé avec les données personnelles et par /reset.
import { prisma } from "@linkaffipro/db";
import { logger } from "./logger";
import { startAccount, type LiveAccount } from "./client";

const live: LiveAccount[] = [];
let stopping = false;

async function main() {
  logger.info("programme userbot demarre");
  const accounts = await prisma.telegramUserAccount.findMany({
    where: { isActive: true, status: "ACTIVE" },
    orderBy: { createdAt: "asc" },
  });
  if (accounts.length === 0) {
    logger.warn("aucun compte actif : connecte un compte depuis /settings/accounts puis relance");
  }
  for (const account of accounts) {
    try {
      live.push(await startAccount({ id: account.id, label: account.label, phone: account.phone }));
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      logger.error({ compte: account.label, err: message }, "connexion impossible");
      await prisma.telegramUserAccount
        .update({ where: { id: account.id }, data: { status: "ERROR", lastError: message.slice(0, 500) } })
        .catch(() => undefined);
    }
  }
  logger.info({ connectes: live.length }, "comptes connectes");
}

async function shutdown(signal: string) {
  if (stopping) return;
  stopping = true;
  logger.info({ signal }, "arret en cours");
  const timer = setTimeout(() => process.exit(1), 15_000);
  try {
    await Promise.all(live.map((a) => a.stop()));
    await prisma.$disconnect();
  } finally {
    clearTimeout(timer);
    process.exit(0);
  }
}

process.on("SIGTERM", () => void shutdown("SIGTERM"));
process.on("SIGINT", () => void shutdown("SIGINT"));
process.on("unhandledRejection", (reason) => logger.error({ reason }, "promesse non geree"));

void main().catch((err: Error) => {
  logger.error({ err: err.message }, "demarrage impossible");
});
