      lastAssistantAt: conv.lastAssistantAt,
    },
    history,
    inbound: [{ id: rec.inboundId, text: msg.text, at: new Date() }],
  };

  const deps: TurnDeps = {
    llm: createVeniceClient(settings.apiKey),
    sender: createMtprotoTransport({
      client: account.client,
      peer: msg.peer,
      conversationId: conv.id,
      memberId: rec.memberId,
      turnId,
    }),
