  lastName: string | null;
  username: string | null;
  languageCode: string | null;
};

// Une conversation a la fois par compte et par personne : jamais deux reponses en parallele.
const busy = new Set<string>();

export async function handleIncomingPrivate(
  account: TurnAccount,
  msg: IncomingPrivate,
): Promise<void> {
  const log = { compte: account.label, de: String(msg.telegramUserId) };
  if (!account.botId || !account.personaId) {
    logger.warn(log, "compte sans bot fantome ou sans persona : message ignore");
    return;
  }
  const lockKey = `${account.id}:${msg.telegramUserId}`;
  const locked = busy.has(lockKey);
  if (!locked) busy.add(lockKey);
  try {
    const turnId = randomUUID();
    const recorded = await recordInbound(account.botId, account.personaId, msg, turnId);
    if (!recorded) return;
    if (locked) {
      // Regroupement des messages arrives pendant un tour : hors perimetre de cette etape.
      logger.info(log, "tour deja en cours : message enregistre sans reponse");
      return;
    }
    const result = await runConversationTurn(account, msg, recorded, turnId);
    if (result)
      logger.info(
