 * Tour de conversation d'un compte reel (phase 18, tache 04) : un message prive recu → reponse du moteur
 * `@linkaffipro/chat` (`runTurn`), envoyee par la session MTProto du compte (transport.ts).
 * Le worker ne touche pas ces conversations (bot fantome en mode STANDARD) : tout le tour se tient ici.
 */
import { randomUUID } from "node:crypto";
import {
  HISTORY_LIMIT,
  clampMaxTokens,
  createVeniceClient,
  estimateCostEur,
  findModel,
  modelSupportsReasoning,
  parisMonthStart,
  parseFacts,
  parseStyleProfile,
  runTurn,
  type HistoryMessage,
  type TurnDeps,
  type TurnInput,
  type TurnResult,
} from "@linkaffipro/chat";
import { Prisma, prisma, toJsonValue } from "@linkaffipro/db";
import type { TelegramClient } from "telegram";
import { logger } from "./logger";
import { loadUserbotSettings } from "./settings";
import { createMtprotoTransport, type TransportPeer } from "./transport";

/** Compte qui recoit le message : son bot fantome et sa persona portent la conversation. */
export type TurnAccount = {
  id: string;
  label: string;
  botId: string | null;
  personaId: string | null;
  client: TelegramClient;
};

/** Message prive entrant, deja reduit a ce dont le tour a besoin (client.ts). */
export type IncomingPrivate = {
  telegramUserId: bigint;
  telegramMessageId: number;
  text: string;
  peer: TransportPeer;
  firstName: string | null;
  lastName: string | null;
  username: string | null;
  languageCode: string | null;
};

// Une conversation a la fois par compte et par personne : jamais deux reponses en parallele.
const busy = new Set<string>();

export async function handleIncomingPrivate(
  account: TurnAccount,
  msg: IncomingPrivate,
): Promise<void> {
  const log = { compte: account.label, de: String(msg.telegramUserId) };
  if (!account.botId || !account.personaId) {
    logger.warn(log, "compte sans bot fantome ou sans persona : message ignore");
    return;
  }
  const lockKey = `${account.id}:${msg.telegramUserId}`;
  const locked = busy.has(lockKey);
  if (!locked) busy.add(lockKey);
  try {
    const turnId = randomUUID();
    const recorded = await recordInbound(account.botId, account.personaId, msg, turnId);
    if (!recorded) return;
    if (locked) {
      // Regroupement des messages arrives pendant un tour : hors perimetre de cette etape.
      logger.info(log, "tour deja en cours : message enregistre sans reponse");
      return;
    }
    const result = await runConversationTurn(account, msg, recorded, turnId);
    if (result)
      logger.info(
        { ...log, entrants: 1, outcome: result.outcome, partis: result.sent.length },
        "tour termine",
      );
  } catch (err) {
    logger.error({ ...log, err: err instanceof Error ? err.message : String(err) }, "tour en echec");
  } finally {
    if (!locked) busy.delete(lockKey);
  }
}

type Recorded = { conversationId: string; memberId: string; inboundId: string };

/**
 * Membre, conversation et message entrant. Le compteur et l'heure du dernier message de la personne sont avances
 * des la reception : le moteur attend `memberMessages` « y compris ceux de ce tour ».
 */
async function recordInbound(
  botId: string,
  personaId: string,
  msg: IncomingPrivate,
  turnId: string,
): Promise<Recorded | null> {
  const now = new Date();
  const member = await prisma.member.upsert({
    where: { telegramUserId: msg.telegramUserId },
    create: {
      telegramUserId: msg.telegramUserId,
      firstName: msg.firstName,
      lastName: msg.lastName,
      username: msg.username,
      languageCode: msg.languageCode,
    },
    update: { lastSeenAt: now },
    select: { id: true },
  });
  const conversation = await prisma.conversation.upsert({
    where: { botId_memberId: { botId, memberId: member.id } },
    create: { botId, memberId: member.id, personaId },
    update: {},
    select: { id: true },
  });
  try {
    // turnId pose sans claimedAt : le balayage du worker (tours bloques, messages non traites) les ignore.
    const inbound = await prisma.conversationMessage.create({
      data: {
        conversationId: conversation.id,
        direction: "IN",
        author: "MEMBER",
        text: msg.text,
        telegramMessageId: BigInt(msg.telegramMessageId),
        turnId,
      },
      select: { id: true },
    });
    await prisma.conversation.update({
      where: { id: conversation.id },
      data: { memberMessages: { increment: 1 }, lastInboundAt: now },
    });
    return { conversationId: conversation.id, memberId: member.id, inboundId: inbound.id };
  } catch (err) {
    // Meme message recu deux fois (reconnexion GramJS) : un seul tour.
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") return null;
    throw err;
  }
}

async function loadHistory(conversationId: string, inboundId: string): Promise<HistoryMessage[]> {
  const rows = await prisma.conversationMessage.findMany({
    where: { conversationId, id: { not: inboundId } },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: HISTORY_LIMIT,
    select: { direction: true, author: true, text: true, createdAt: true },
  });
  return rows.reverse().map((r) => ({
    direction: r.direction,
    author: r.author,
    text: r.text,
    at: r.createdAt,
  }));
}

async function monthSpendEur(now: Date): Promise<number> {
  const agg = await prisma.aiConversationUsage.aggregate({
    _sum: { costEur: true },
    where: { createdAt: { gte: parisMonthStart(now) } },
  });
  return Number(agg._sum.costEur ?? 0);
}

async function runConversationTurn(
  account: TurnAccount,
  msg: IncomingPrivate,
  rec: Recorded,
  turnId: string,
): Promise<TurnResult | null> {
  const log = { compte: account.label, de: String(msg.telegramUserId) };
  const [settings, persona, conv] = await Promise.all([
    loadUserbotSettings(),
    prisma.persona.findUnique({ where: { id: account.personaId! } }),
    prisma.conversation.findUniqueOrThrow({
      where: { id: rec.conversationId },
      include: { member: { select: { languageCode: true } } },
    }),
  ]);
  if (!settings.apiKey) {
    logger.warn(log, "cle Venice absente : pas de reponse");
    return null;
  }
  if (!persona) {
    logger.warn(log, "persona introuvable : pas de reponse");
    return null;
  }
  // Conversation fermee, /stop ou mineur : jamais de reponse (la reprise par l'equipe viendra plus tard).
  if (conv.status !== "BOT" || conv.stoppedAt || conv.isMinor) {
    logger.info({ ...log, statut: conv.status }, "conversation fermee : pas de reponse");
    return null;
  }

  const cfg = settings.config;
  const modelId = persona.model?.trim() || cfg.defaultModel;
  const history = await loadHistory(conv.id, rec.inboundId);
  const input: TurnInput = {
    kind: "reply",
    persona: {
      name: persona.name,
      gender: persona.gender,
      personality: persona.personality,
      tone: persona.tone,
      languages: persona.languages,
      interests: persona.interests,
      extraPrompt: persona.extraPrompt,
      model: persona.model,
      temperature: persona.temperature,
      minExchangesBeforeOffer: persona.minExchangesBeforeOffer,
      requireInterest: persona.requireInterest,
      maxOfferSends: persona.maxOfferSends,
      followUpAfterHours: persona.followUpAfterHours,
      followUpsMax: persona.followUpsMax,
      offerPitch: persona.offerPitch,
      offerButtonText: persona.offerButtonText,
      hasOffer: persona.affiliateCampaignId !== null,
      offerMediaAssetId: persona.offerMediaAssetId,
    },
    settings: {
      defaultModel: cfg.defaultModel,
      fallbackModel: cfg.fallbackModel,
      temperature: cfg.temperature,
      maxTokens: clampMaxTokens(cfg.maxTokens, findModel(modelId, cfg.models)),
      modelSupportsReasoning: (id) => modelSupportsReasoning(id, cfg.models),
    },
    conversation: {
      stage: conv.stage,
      style: parseStyleProfile(conv.styleProfile),
      summary: conv.summary,
      facts: parseFacts(conv.facts),
      memberMessages: conv.memberMessages,
      assistantTurns: conv.assistantTurns,
      offerSends: conv.offerSends,
      followUpCount: conv.followUpCount,
      isMinor: conv.isMinor,
      isFirstAssistantTurn: conv.assistantTurns === 0,
      memberLanguageCode: conv.member.languageCode,
      lastInboundAt: conv.lastInboundAt,
      lastAssistantAt: conv.lastAssistantAt,
    },
    history,
    inbound: [{ id: rec.inboundId, text: msg.text, at: new Date() }],
  };

  const deps: TurnDeps = {
    llm: createVeniceClient(settings.apiKey),
    sender: createMtprotoTransport({
      client: account.client,
      peer: msg.peer,
      conversationId: conv.id,
      memberId: rec.memberId,
      turnId,
    }),
    now: () => new Date(),
    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    random: () => Math.random(),
    // Le lien d'offre des comptes reels viendra dans une etape suivante.
    createOfferLink: async () => null,
    beforeSend: async () => ({ abort: false, newInbound: [] }),
    recordUsage: async (u) => {
      await prisma.aiConversationUsage.create({
        data: {
          personaId: persona.id,
          conversationId: conv.id,
          source: conv.source,
          purpose: u.purpose,
          model: u.model.slice(0, 200),
          inputTokens: Math.max(0, Math.round(u.inputTokens)),
          outputTokens: Math.max(0, Math.round(u.outputTokens)),
          costEur: u.costEur,
          ok: u.ok,
          error: u.error?.slice(0, 200) ?? null,
          attempt: u.attempt,
          requestId: u.requestId?.slice(0, 200) ?? null,
        },
      });
    },
    capReached: async () => (await monthSpendEur(new Date())) >= cfg.monthlyCapEur,
    costEur: (model, usage, costUsd) => estimateCostEur(model, usage, costUsd, cfg.models),
  };

  const result = await runTurn(input, deps);
  await persistResult(conv.id, conv.stage, result);
  return result;
}

/** Etat de la conversation apres le tour (etape, style, faits, compteurs ; fermeture si la personne est perdue). */
async function persistResult(
  conversationId: string,
  stageBefore: TurnResult["newStage"],
  r: TurnResult,
): Promise<void> {
  const now = new Date();
  const data: Prisma.ConversationUpdateInput = {
    styleProfile: toJsonValue(r.style),
    facts: toJsonValue(r.facts),
    language: r.language,
  };
  if (r.newStage !== stageBefore) data.stage = r.newStage;
  if (r.outcome === "replied") data.assistantTurns = { increment: 1 };
  if (r.sent.length > 0) data.lastAssistantAt = now;
  if (r.offerSent) data.offerSends = { increment: 1 };
  const closeReason = r.outcome === "minor" ? "MINOR" : r.closeReason;
  if (closeReason) {
    data.status = "CLOSED";
    data.stage = "CLOSED";
    data.closedAt = now;
    data.closedReason = closeReason;
    if (closeReason === "MINOR") data.isMinor = true;
  }
  await prisma.conversation.update({ where: { id: conversationId }, data });
}
